<template><section><div class="dashboard-grid"><section class="paper-card metric-card" v-for="m in cards" :key="m.label"><span>{{m.label}}</span><strong>{{m.value}}</strong><p>{{m.tip}}</p></section></div><div class="chart-grid"><div class="paper-card chart-card" ref="trendRef"></div><div class="paper-card chart-card" ref="pieRef"></div><div class="paper-card chart-card" ref="hotRef"></div></div></section></template>
<script setup>import{computed,nextTick,onMounted,ref}from'vue';import*as echarts from'echarts';import{api}from'../api/library';const overview=ref({});const trend=ref([]),dist=ref([]);const trendRef=ref(),pieRef=ref(),hotRef=ref();const cards=computed(()=>[{label:'图书总量',value:overview.value.book_total||0,tip:'馆藏书目'},{label:'可借库存',value:overview.value.available_total||0,tip:'当前可借册数'},{label:'读者数量',value:overview.value.reader_total||0,tip:'注册读者'},{label:'逾期记录',value:overview.value.overdue_total||0,tip:'需重点处理'}]);function draw(){echarts.init(trendRef.value).setOption({title:{text:'借阅趋势'},xAxis:{type:'category',data:trend.value.map(i=>i.name)},yAxis:{type:'value'},series:[{type:'line',smooth:true,data:trend.value.map(i=>i.value),areaStyle:{}}]});echarts.init(pieRef.value).setOption({title:{text:'分类借阅占比'},tooltip:{},series:[{type:'pie',radius:['45%','70%'],data:dist.value}]});echarts.init(hotRef.value).setOption({title:{text:'热门图书'},xAxis:{type:'value'},yAxis:{type:'category',data:(overview.value.hotBooks||[]).map(i=>i.name)},series:[{type:'bar',data:(overview.value.hotBooks||[]).map(i=>i.value)}]})}onMounted(async()=>{overview.value=(await api.overview()).data||{};trend.value=(await api.trend()).data||[];dist.value=(await api.categoryDistribution()).data||[];await nextTick();draw()})</script>
